"use client";

import "../../styles/whatiuse-base.css";
import "../../styles/components/textarea.css";
import { useId, useState, type ComponentPropsWithRef } from "react";
import { cn } from "../../lib/cn";

export type TextareaProps = ComponentPropsWithRef<"textarea"> & {
  label?: string;
  description?: string;
  error?: string;
  showCount?: boolean;
};

export function Textarea({ id: providedId, label, description, error, showCount, maxLength, className, value, defaultValue, onChange, ref, ...props }: TextareaProps) {
  const generatedId = useId();
  const id = providedId ?? generatedId;
  const descriptionId = description ? `${id}-description` : undefined;
  const errorId = error ? `${id}-error` : undefined;
  const describedBy = [props["aria-describedby"], descriptionId, errorId].filter(Boolean).join(" ") || undefined;
  const initialValue = value ?? defaultValue ?? "";
  const [uncontrolledCount, setUncontrolledCount] = useState(typeof initialValue === "string" ? initialValue.length : 0);
  const count = typeof value === "string" ? value.length : uncontrolledCount;

  return (
    <div className="whatiuse-field whatiuse-textarea-field" data-invalid={Boolean(error) || undefined}>
      {label && <label className="whatiuse-field__label" htmlFor={id}>{label}</label>}
      <textarea
        ref={ref}
        id={id}
        className={cn("whatiuse-input whatiuse-textarea", className)}
        aria-invalid={Boolean(error) || undefined}
        aria-describedby={describedBy}
        maxLength={maxLength}
        value={value}
        defaultValue={defaultValue}
        onChange={(event) => { setUncontrolledCount(event.currentTarget.value.length); onChange?.(event); }}
        {...props}
      />
      <div className="whatiuse-textarea-field__meta">
        <span>
          {description && <span id={descriptionId} className="whatiuse-field__description">{description}</span>}
          {error && <span id={errorId} className="whatiuse-field__error">{error}</span>}
        </span>
        {showCount && maxLength && <output aria-label="Character count">{count}/{maxLength}</output>}
      </div>
    </div>
  );
}

/* Generated from src/foundation.css and src/styles.css. Do not edit directly. */

@layer whatiuse.tokens, whatiuse.base, whatiuse.components;

@layer whatiuse.components {
.whatiuse-textarea {
  box-sizing: border-box;
  max-width: 100%;
  min-height: 96px;
  resize: vertical;
  padding: 9px 10px;
  line-height: 1.5;
}

.whatiuse-textarea-field__meta { display: flex; align-items: flex-start; justify-content: space-between; gap: 12px; }

.whatiuse-textarea-field__meta > span { min-width: 0; }

.whatiuse-textarea-field__meta output { flex: 0 0 auto; color: var(--whatiuse-ink-tertiary); font-size: var(--whatiuse-type-metadata); font-variant-numeric: tabular-nums; }

.whatiuse-field { display: grid; min-width: 0; gap: 6px; }

.whatiuse-field__label { color: var(--whatiuse-ink); font-size: 12px; font-weight: 550; }

.whatiuse-field[data-invalid] .whatiuse-field__control { border-color: color-mix(in oklch, var(--whatiuse-fg-danger) 46%, var(--whatiuse-control-border)); box-shadow: 0 0 0 2px color-mix(in oklch, var(--whatiuse-fg-danger) 11%, transparent); }

.whatiuse-input { width: 100%; min-width: 0; height: 100%; padding: 0 9px; border: 0; outline: 0; background: transparent; color: var(--whatiuse-ink); font-size: 13.5px; }

.whatiuse-input::placeholder { color: var(--whatiuse-fg-subtle); }

.whatiuse-input:disabled { background: var(--whatiuse-bg-subtle); color: var(--whatiuse-fg-disabled); cursor: not-allowed; }

.whatiuse-input:read-only { color: var(--whatiuse-fg-muted); }

.whatiuse-field__description,
.whatiuse-field__error { color: var(--whatiuse-ink-tertiary); font-size: 11.5px; line-height: 1.45; }

.whatiuse-field__error { color: var(--whatiuse-fg-danger); font-weight: 520; }

:root[data-theme="dark"] .whatiuse-input:disabled { background: rgb(255 255 255 / 0.025); color: var(--whatiuse-ink-disabled); }
}
